// Dual-axis QuickChart: response volume as bars, metric as a line. Deterministic, no LLM.
const inp = $('Defaults').first().json;

const META = {
  volume:          { label: 'Service requests', color: '#2f6fd0', bars: false },
  resolution_rate: { label: 'Resolution rate %', color: '#1f9d55', bars: true  },
  csat:            { label: 'CSAT',              color: '#c2410c', bars: true  },
};
let metric = String(inp.metric || 'csat').toLowerCase().trim();
if (!META[metric]) metric = 'csat';
const m = META[metric];

const rows = $input.all().map(i => i.json).filter(r => r.week);
if (!rows.length) {
  return [{ json: { error: 'no rows for that filter', chart_markdown: '' } }];
}

const parts = [];
if (inp.country  && inp.country  !== 'ALL') parts.push(inp.country);
if (inp.l1_topic && inp.l1_topic !== 'ALL') parts.push(inp.l1_topic);
if (inp.channel  && inp.channel  !== 'ALL') parts.push(inp.channel);
const scope = parts.join(' / ') || 'All countries & topics';

const labels = rows.map(r => String(r.week).slice(5));
const line   = rows.map(r => (r[metric] == null ? null : Number(r[metric])));
const bars   = rows.map(r => Number(r.csat_response_cnt || 0));

const datasets = [{
  type: 'line', label: m.label, data: line, yAxisID: 'L',
  borderColor: m.color, backgroundColor: m.color, fill: false, tension: 0.3,
  pointRadius: 3, borderWidth: 2,
}];
// Response-count bars only make sense behind a survey-based metric
if (m.bars) {
  datasets.push({
    type: 'bar', label: 'CSAT responses', data: bars, yAxisID: 'R',
    backgroundColor: 'rgba(120,130,145,0.30)', borderWidth: 0,
  });
}

const cfg = {
  type: 'bar',
  data: { labels, datasets },
  options: {
    title: { display: true, text: `${m.label} — ${scope}` },
    legend: { display: m.bars, position: 'bottom' },
    scales: {
      xAxes: [{ scaleLabel: { display: true, labelString: 'Week beginning' } }],
      yAxes: m.bars ? [
        { id: 'L', position: 'left',  scaleLabel: { display: true, labelString: m.label } },
        { id: 'R', position: 'right', scaleLabel: { display: true, labelString: 'Responses' },
          gridLines: { drawOnChartArea: false }, ticks: { beginAtZero: true } },
      ] : [
        { id: 'L', position: 'left', scaleLabel: { display: true, labelString: m.label } },
      ],
    },
  },
};

const url = 'https://quickchart.io/chart?w=720&h=340&bkg=white&c=' +
            encodeURIComponent(JSON.stringify(cfg));

const f = line[0], l = line[line.length - 1];
return [{ json: {
  chart_markdown: `![${m.label} trend](${url})`,
  instruction: 'Copy the chart_markdown value into your reply exactly as written, on its own line. Do not describe it, shorten it, or rewrite the URL.',
  summary: `${m.label} for ${scope}: ${f} on ${rows[0].week} to ${l} on ${rows[rows.length-1].week} across ${rows.length} weeks.`,
  series: rows.map((r, i) => ({ week: r.week, value: line[i] })),
}}];
